### Description

Repro:
```csharp
using System.Numerics;

static U Foo<T, U>(U x, U y)
    where T : I1, I2
    where U : IAdditionOperators<U, U, U>,
        ISubtractionOperators<U, U, U>,
        IMultiplyOperators<U, U, U>,
        IDivisionOperators<U, U, U>
    => Foo1<T, U>(x, y) + Foo2<T, U>(x, y);
static U Foo1<T, U>(U x, U y)
    where T : I1
    where U : IAdditionOperators<U, U, U>,
        ISubtractionOperators<U, U, U>,
        IMultiplyOperators<U, U, U>,
        IDivisionOperators<U, U, U>
    => T.Foo(x, y);
static U Foo2<T, U>(U x, U y)
    where T : I2
    where U : IAdditionOperators<U, U, U>,
        ISubtractionOperators<U, U, U>,
        IMultiplyOperators<U, U, U>,
        IDivisionOperators<U, U, U>
    => T.Foo(x, y);

Console.WriteLine(Test());

static int Test()
{
    int a = default;
    int b = default;
    int sum = default;
    sum += Foo<C1, int>(++a, ++a);
    sum *= Foo<C2, int>(++b, ++b);
    a = sum * 2;
    sum /= Foo<C3, int>(++a * b, a / b);
    sum -= a + b;
    sum -= Foo1<C4, int>(--a, ++b);
    b = sum / 2;
    sum += Foo2<C5, int>(a / b, a * b - 1);
    sum *= Foo<C6, int>(a, b);
    return sum;
}

interface I1
{
    virtual static T Foo<T>(T l, T r)
        where T : IAdditionOperators<T, T, T>,
            ISubtractionOperators<T, T, T>,
            IMultiplyOperators<T, T, T>,
            IDivisionOperators<T, T, T>
        => l + r;
}
interface I2
{
    abstract static T Foo<T>(T l, T r)
        where T : IAdditionOperators<T, T, T>,
            ISubtractionOperators<T, T, T>,
            IMultiplyOperators<T, T, T>,
            IDivisionOperators<T, T, T>;
}
interface I : I1, I2
{
    static T I1.Foo<T>(T l, T r) => l - r;
    static T I2.Foo<T>(T l, T r) => l * r;
}
class C1 : I { }
class C2 : I
{
    public static T Foo<T>(T l, T r)
        where T : IAdditionOperators<T, T, T>,
            ISubtractionOperators<T, T, T>,
            IMultiplyOperators<T, T, T>,
            IDivisionOperators<T, T, T>
        => l / r;
}
class C3 : I
{
    static T I1.Foo<T>(T l, T r) => l + r * l;
    static T I2.Foo<T>(T l, T r) => l - r * l;
}
class C4 : I1 { }
class C5 : I2
{
    public static T Foo<T>(T l, T r)
        where T : IAdditionOperators<T, T, T>,
            ISubtractionOperators<T, T, T>,
            IMultiplyOperators<T, T, T>,
            IDivisionOperators<T, T, T>
        => l / r - r;
}
class C6 : I1, I2
{
    public static T Foo<T>(T l, T r)
        where T : IAdditionOperators<T, T, T>,
            ISubtractionOperators<T, T, T>,
            IMultiplyOperators<T, T, T>,
            IDivisionOperators<T, T, T>
        => l / r + r;
}
```

